use stdpython :: * ; use tokio ; pub async fn fetch_data () -> Result < & 'static str , PyException > { asyncio :: sleep (1) . await ; return Ok ("data") ; } pub fn process_data (data : impl Into < PyObject >) -> Result < String , PyException > { return Ok (format ! ("Processed: {}" , py_display (& (data)))) ; } pub async fn python_main () -> Result < () , PyException > { let data ; let result ; data = fetch_data () . await ? ; ; result = process_data (data) ? ; ; print (& (result)) ; Ok (()) } pub async fn another_async () -> Result < & 'static str , PyException > { return Ok ("another") ; } # [tokio :: main] async fn main () { let __rython_result : Result < () , PyException > = async { asyncio :: run (python_main () ?) ; print (& ("Second main block")) ; Ok (()) } . await ; if let Err (e) = __rython_result { eprintln ! ("{}" , e) ; std :: process :: exit (1) ; } }